with lines as (select id, customer_id, created_at, element from carts lateral view explode(coupon_codes) x as element), joined as (select a.*, c.email, c.city from lines a inner join customers c on a.customer_id = c.id), valid as (select *, case when element = 'WELCOME5' then 1 else 0 end as is_welcome5 from joined where element = 'VIP'), with_windows as (select *, percent_rank() over (order by is_welcome5) as is_welcome5_percent_rank, cume_dist() over (order by is_welcome5 desc nulls last) as is_welcome5_cume_dist, max(is_welcome5) over (partition by customer_id, element order by cast(created_at as bigint) range between 3600 preceding and current row) as is_welcome5_max_1h, sum(is_welcome5) over (partition by element) as element_sum_is_welcome5, sum(is_welcome5) over w_running as customer_id_sum_is_welcome5 from valid window w_running as (partition by customer_id)) select case when is_welcome5_percent_rank >= 0.61 then 'HIGH' else 'LOW' end as is_welcome5_percent_rank_tier, city, round(avg(is_welcome5_cume_dist), 2) as avg_is_welcome5_cume_dist, sum(case when element = 'BUNDLE' then element_sum_is_welcome5 else 0 end) as bundle_element_sum_is_welcome5, count(distinct element) as distinct_elements, count(distinct city) as distinct_cities, grouping_id() as gid from with_windows group by grouping sets ((case when is_welcome5_percent_rank >= 0.61 then 'HIGH' else 'LOW' end, city), (case when is_welcome5_percent_rank >= 0.61 then 'HIGH' else 'LOW' end));
